import os, json, re, importlib.util

def load_all():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_all()
test_input = G['Test input']
print(f"Test input shape: {len(test_input)}x{len(test_input[0])}")

from collections import Counter
n = Counter(c for row in test_input for c in row)
dot = n.most_common()[-1][0]
print(f"Background: {n.most_common()[0][0]}, Dot (least common): {dot}")

# Create proper transform function
def transform(grid):
    from collections import Counter
    n = Counter(c for row in grid for c in row)
    dot = n.most_common()[-1][0]
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Fill between dots in each row
    for r in range(H):
        cols = [c for c in range(W) if grid[r][c] == dot]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if out[r][c] != dot:
                    out[r][c] = 3

    # Fill between dots in each column
    for c in range(W):
        rws = [r for r in range(H) if grid[r][c] == dot]
        if len(rws) >= 2:
            for r in range(min(rws) + 1, max(rws)):
                if out[r][c] != dot:
                    out[r][c] = 3

    return out

result = transform(test_input)
print("\n=== Output grid ===")
for i, row in enumerate(result):
    print(f"Row {i}: {row}")

